-- V-022 (run O1, session.sh): after 022-photos-admin.sql
-- Read only, in a read-only transaction. Each row is: ok or KO | what | the number found. Never a name, an e-mail or a row of a person.
-- From the Verify lines of the file's header and its self-check: what 022 must leave, each as a row that stops the part when it is KO.
begin transaction read only;
select case when ok is true then 'ok' else 'KO' end, what, coalesce(got, '-') from (values
  (1, 'agencies et site_assets avec RLS, aucune policy', (select count(*) = 2 from pg_class c where c.oid in (to_regclass('public.agencies'), to_regclass('public.site_assets')) and c.relrowsecurity and not exists (select 1 from pg_policy p where p.polrelid = c.oid)), (select count(*)::text from pg_class c where c.oid in (to_regclass('public.agencies'), to_regclass('public.site_assets')) and c.relrowsecurity and not exists (select 1 from pg_policy p where p.polrelid = c.oid))),
  (2, 'colonnes : agencies 8, site_assets 20', (select count(*) = 8 from information_schema.columns where table_schema = 'public' and table_name = 'agencies' and column_name in ('id', 'slug', 'name', 'parent_id', 'official_url', 'sources', 'created_at', 'updated_at')) and (select count(*) = 20 from information_schema.columns where table_schema = 'public' and table_name = 'site_assets' and column_name in ('id', 'key', 'type', 'page', 'settings', 'path', 'mid_path', 'thumb_path', 'width', 'height', 'source_url', 'author', 'license', 'license_note', 'license_verified', 'published_at', 'retired_at', 'created_by', 'created_at', 'updated_at')), (select count(*)::text from information_schema.columns where table_schema = 'public' and table_name in ('agencies', 'site_assets'))),
  (3, 'entity_images : 5 contraintes validées (5 genres dont agency, slug, site kpop, 96 px si vérifiée, source https)', (select count(*) = 5 from pg_constraint where conrelid = to_regclass('public.entity_images') and convalidated and conname in ('entity_images_kind_check', 'entity_images_slug_check', 'entity_images_kind_site_check', 'entity_images_verified_thumb_check', 'entity_images_kpop_source_check')) and (select pg_get_constraintdef(oid) ~ 'idol' and pg_get_constraintdef(oid) ~ 'group' and pg_get_constraintdef(oid) ~ 'agency' from pg_constraint where conrelid = to_regclass('public.entity_images') and conname = 'entity_images_kind_check'), (select count(*)::text from pg_constraint where conrelid = to_regclass('public.entity_images') and convalidated and conname in ('entity_images_kind_check', 'entity_images_slug_check', 'entity_images_kind_site_check', 'entity_images_verified_thumb_check', 'entity_images_kpop_source_check'))),
  (4, 'site_assets : 20 checks validés, dont publication = licence vérifiée, crédit, icônes et stickers sans CC', (select count(*) = 20 and bool_and(convalidated) from pg_constraint where conrelid = to_regclass('public.site_assets') and contype = 'c') and (select count(*) = 3 from pg_constraint where conrelid = to_regclass('public.site_assets') and conname in ('site_assets_published_check', 'site_assets_credit_check', 'site_assets_small_license_check')), (select count(*)::text from pg_constraint where conrelid = to_regclass('public.site_assets') and contype = 'c')),
  (5, 'agencies : 5 checks validés (slug, nom, site https, sources https, pas sa propre mère)', (select count(*) = 5 from pg_constraint where conrelid = to_regclass('public.agencies') and contype = 'c' and convalidated and conname in ('agencies_slug_check', 'agencies_name_check', 'agencies_official_url_check', 'agencies_sources_check', 'agencies_parent_self_check')), (select count(*)::text from pg_constraint where conrelid = to_regclass('public.agencies') and contype = 'c')),
  (6, 'déclencheurs actifs : la licence retombe sur un nouveau fichier ou crédit (2), updated_at (2)', (select count(*) = 4 from pg_trigger where not tgisinternal and tgenabled = 'O' and ((tgrelid = to_regclass('public.entity_images') and tgname in ('trg_entity_images_licence_listed', 'trg_entity_images_licence_reset')) or (tgrelid = to_regclass('public.agencies') and tgname = 'trg_agencies_touch') or (tgrelid = to_regclass('public.site_assets') and tgname = 'trg_site_assets_touch'))) and (select pg_get_triggerdef(oid) ~ 'BEFORE UPDATE OF license_verified' from pg_trigger where tgrelid = to_regclass('public.entity_images') and tgname = 'trg_entity_images_licence_listed'), (select count(*)::text from pg_trigger where not tgisinternal and tgenabled = 'O' and tgname in ('trg_entity_images_licence_listed', 'trg_entity_images_licence_reset', 'trg_agencies_touch', 'trg_site_assets_touch'))),
  (7, 'les 4 fonctions de 022 fermées à anon et authenticated', (select count(*) = 4 and bool_and(not has_function_privilege('anon', oid, 'execute') and not has_function_privilege('authenticated', oid, 'execute')) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('entity_images_licence_listed', 'entity_images_licence_reset', 'photos_touch', 'agencies_sources_ok')), (select count(*)::text from pg_proc where pronamespace = 'public'::regnamespace and proname in ('entity_images_licence_listed', 'entity_images_licence_reset', 'photos_touch', 'agencies_sources_ok'))),
  (8, 'entity_images : la lecture directe réduite à series et character (idol, group, agency par la vue seulement)', (select count(*) = 1 from pg_policy where polrelid = to_regclass('public.entity_images') and polcmd in ('r', '*')) and (select pg_get_expr(polqual, polrelid) ~ 'series' and pg_get_expr(polqual, polrelid) ~ 'character' and pg_get_expr(polqual, polrelid) !~ '(idol|group|agency)' from pg_policy where polrelid = to_regclass('public.entity_images') and polname = 'entity_images_select_display'), null),
  (9, 'entity_images : droits de 018 et 019 inchangés (anon sans insert, authenticated sans update, licence et 96 px illisibles par anon)', (select not has_table_privilege('anon', 'public.entity_images', 'insert') and not has_table_privilege('authenticated', 'public.entity_images', 'update') and not has_column_privilege('anon', 'public.entity_images', 'license_verified', 'select') and not has_column_privilege('anon', 'public.entity_images', 'thumb_path', 'select')), null),
  (10, 'agencies et site_assets fermées à anon et authenticated, ouvertes au service_role', (select count(*) = 0 from (values ('anon'), ('authenticated')) as r(role) cross join (values ('public.agencies'), ('public.site_assets')) as t(tab) cross join (values ('select'), ('insert'), ('update'), ('delete'), ('truncate'), ('references'), ('trigger')) as p(priv) where to_regclass(t.tab) is null or has_table_privilege(r.role, t.tab, p.priv)) and (select bool_and(has_table_privilege('service_role', t.tab, 'select') and has_table_privilege('service_role', t.tab, 'insert') and has_table_privilege('service_role', t.tab, 'update') and has_table_privilege('service_role', t.tab, 'delete')) from (values ('public.agencies'), ('public.site_assets')) as t(tab)), (select count(*)::text from (values ('anon'), ('authenticated')) as r(role) cross join (values ('public.agencies'), ('public.site_assets')) as t(tab) cross join (values ('select'), ('insert'), ('update'), ('delete'), ('truncate'), ('references'), ('trigger')) as p(priv) where to_regclass(t.tab) is null or has_table_privilege(r.role, t.tab, p.priv))),
  (11, 'séquences agencies_id_seq et site_assets_id_seq fermées à anon et authenticated', (select count(*) = 0 from (values ('anon'), ('authenticated')) as r(role) cross join (values ('public.agencies_id_seq'), ('public.site_assets_id_seq')) as s(seq) cross join (values ('usage'), ('select'), ('update')) as p(priv) where to_regclass(s.seq) is null or has_sequence_privilege(r.role, s.seq, p.priv)), (select count(*)::text from (values ('anon'), ('authenticated')) as r(role) cross join (values ('public.agencies_id_seq'), ('public.site_assets_id_seq')) as s(seq) cross join (values ('usage'), ('select'), ('update')) as p(priv) where to_regclass(s.seq) is null or has_sequence_privilege(r.role, s.seq, p.priv))),
  (12, 'vues site_assets_public et entity_images_public : lecture seule pour anon et authenticated', (select count(*) = 2 and bool_and(has_table_privilege('anon', c.oid, 'select') and has_table_privilege('authenticated', c.oid, 'select') and not has_table_privilege('anon', c.oid, 'insert, update, delete') and not has_table_privilege('authenticated', c.oid, 'insert, update, delete')) from pg_class c where c.oid in (to_regclass('public.site_assets_public'), to_regclass('public.entity_images_public')) and c.relkind = 'v'), null),
  (13, 'entity_images_public : seulement les images vérifiées, avec leur 96 px et une source https', (select pg_get_viewdef('public.entity_images_public'::regclass) ~ 'license_verified' and pg_get_viewdef('public.entity_images_public'::regclass) ~ 'thumb_path IS NOT NULL' and pg_get_viewdef('public.entity_images_public'::regclass) ~ 'source_url ~ ''\^https://'''), null),
  (14, 'site_assets_public : jamais une ligne retirée, à venir, ou une image sans licence vérifiée', (select pg_get_viewdef('public.site_assets_public'::regclass) ~ 'retired_at IS NULL' and pg_get_viewdef('public.site_assets_public'::regclass) ~ 'published_at <= now\(\)' and pg_get_viewdef('public.site_assets_public'::regclass) ~ '\(path IS NULL\) OR license_verified'), null),
  (15, 'agencies : une ligne par label cité par les groupes kpop (17 en production)', (select count(*) = 0 from (select distinct btrim(g.record_label) as name from public.groups g where g.site_id = 'kpop' and nullif(btrim(g.record_label), '') is not null) l where not exists (select 1 from public.agencies a where a.name = l.name)), (select count(*)::text from public.agencies))
) as c(n, what, ok, got) order by n;
rollback;
